# Let me identify the actual CLOSED shapes - ones that have 0s completely surrounded by 8s
from collections import deque

def find_interior_0s(grid):
    """Find all 0s that cannot reach the grid boundary (truly enclosed)"""
    H, W = len(grid), len(grid[0])

    # Find all 0s reachable from boundary
    boundary_zeros = set()
    queue = deque()

    # Start BFS from all boundary 0s
    for r in range(H):
        for c in [0, W-1]:
            if grid[r][c] == 0:
                boundary_zeros.add((r, c))
                queue.append((r, c))

    for c in range(1, W-1):
        for r in [0, H-1]:
            if grid[r][c] == 0 and (r, c) not in boundary_zeros:
                boundary_zeros.add((r, c))
                queue.append((r, c))

    # BFS to find all 0s reachable from boundary
    while queue:
        r, c = queue.popleft()
        for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
            nr, nc = r+dr, c+dc
            if 0 <= nr < H and 0 <= nc < W:
                if grid[nr][nc] == 0 and (nr, nc) not in boundary_zeros:
                    boundary_zeros.add((nr, nc))
                    queue.append((nr, nc))

    # Remaining 0s that are NOT reachable from boundary are enclosed
    interior = set()
    for r in range(H):
        for c in range(W):
            if grid[r][c] == 0 and (r, c) not in boundary_zeros:
                interior.add((r, c))

    return interior

